/*
 * Zigbee Coordinator — Board 1
 * Sends a counter to End Device every 2 seconds
 * Green LED on D2 blinks on each send
 */

#include <Zigbee.h>

// End Device short address (assigned automatically)
uint16_t endDeviceAddr = 0x0001;

// Data structure to send
typedef struct {
  int counter;
  float temperature;
} DataPacket;

DataPacket myData;
int sendCount = 0;

// Callback when data is sent
void onSendStatus(int status) {
  if (status == ZIGBEE_SEND_SUCCESS) {
    Serial.println("[Coordinator] Send OK");
  } else {
    Serial.println("[Coordinator] Send FAILED");
  }
}

void setup() {
  Serial.begin(115200);
  pinMode(2, OUTPUT);

  // Initialize Zigbee on channel 11, PAN ID 0x1234
  Zigbee.begin(11, 0x1234);
  Zigbee.onSend(onSendStatus);

  Serial.println("[Coordinator] Zigbee network started!");
  Serial.print("[Coordinator] Short Address: 0x");
  Serial.println(Zigbee.getNodeAddress(), HEX);
  Serial.print("[Coordinator] PAN ID: 0x");
  Serial.println(Zigbee.getPanId(), HEX);
  Serial.print("[Coordinator] Channel: ");
  Serial.println(Zigbee.getChannel());
  Serial.println();
}

void loop() {
  sendCount++;
  myData.counter = sendCount;
  myData.temperature = 22.5 + (sendCount % 10) * 0.5;

  // Blink LED on send
  digitalWrite(2, HIGH);

  // Send data to End Device
  Zigbee.send(endDeviceAddr, (uint8_t *)&myData, sizeof(myData));

  Serial.print("[Coordinator] Sent #");
  Serial.print(sendCount);
  Serial.print(" temp=");
  Serial.println(myData.temperature);

  digitalWrite(2, LOW);
  delay(2000);
}

