/*
 * Zigbee End Device — Board 2
 * Receives data from Coordinator (Board 1)
 * Blue LED on D2 blinks on each receive
 */

#include <Zigbee.h>

// Data structure to receive
typedef struct {
  int counter;
  float temperature;
} DataPacket;

DataPacket incomingData;

// Callback when data is received
void onDataReceived(uint8_t *data, int len) {
  // Copy data into our struct
  memcpy(&incomingData, data, sizeof(incomingData));

  Serial.print("[End Device] Received #");
  Serial.print(incomingData.counter);
  Serial.print(" temp=");
  Serial.println(incomingData.temperature);

  // Blink LED on receive
  digitalWrite(2, HIGH);
  delay(50);
  digitalWrite(2, LOW);
}

void setup() {
  Serial.begin(115200);
  pinMode(2, OUTPUT);

  // Initialize Zigbee on same channel and PAN
  Zigbee.begin(11, 0x1234);
  Zigbee.onReceive(onDataReceived);

  Serial.println("[End Device] Zigbee node ready!");
  Serial.print("[End Device] Short Address: 0x");
  Serial.println(Zigbee.getNodeAddress(), HEX);
  Serial.print("[End Device] Waiting for data from Coordinator...\n");
}

void loop() {
  delay(100);
}
